#!/usr/bin/env python3
import argparse
import json
from dataclasses import dataclass, asdict
from datetime import date, datetime, timedelta
from pathlib import Path

@dataclass(frozen=True)
class Finding:
    user_id: str
    category: str
    severity: str
    detail: str

SEVERITY_RANK = {"low": 1, "medium": 2, "high": 3, "critical": 4}

def parse_date(value: str) -> date:
    return datetime.strptime(value, "%Y-%m-%d").date()

def analyze(document: dict, review_days: int = 180) -> list[Finding]:
    findings: list[Finding] = []
    today = date.today()
    stale_cutoff = today - timedelta(days=review_days)

    conflict_pairs = {frozenset(pair) for pair in document.get("sod_conflicts", [])}
    for user in document.get("users", []):
        uid = user["id"]
        roles = set(user.get("roles", []))

        if user.get("status") == "disabled" and roles:
            findings.append(Finding(uid, "disabled_with_access", "high",
                                    "Disabled identity still has role assignments."))

        if "admin" in roles and not user.get("mfa", False):
            findings.append(Finding(uid, "privileged_without_mfa", "critical",
                                    "Privileged role is assigned without MFA."))

        review_value = user.get("last_review")
        if review_value and parse_date(review_value) < stale_cutoff:
            findings.append(Finding(uid, "stale_review", "medium",
                                    f"Access review is older than {review_days} days."))

        for pair in conflict_pairs:
            if pair.issubset(roles):
                findings.append(Finding(uid, "sod_conflict", "high",
                                        f"Conflicting roles assigned: {', '.join(sorted(pair))}."))
    return findings

def build_report(document: dict, review_days: int) -> dict:
    findings = analyze(document, review_days)
    highest = "low"
    if findings:
        highest = max((f.severity for f in findings), key=lambda s: SEVERITY_RANK[s])
    return {
        "user_count": len(document.get("users", [])),
        "finding_count": len(findings),
        "highest_severity": highest,
        "findings": [asdict(f) for f in findings],
        "recommended_actions": [
            "Validate findings against authoritative identity records.",
            "Remove or expire unnecessary privileged access.",
            "Review stale access and document business justification.",
            "Preserve audit evidence before making high-impact changes."
        ]
    }

def main() -> int:
    parser = argparse.ArgumentParser(description="Local IAM access-governance analyzer")
    parser.add_argument("input", type=Path)
    parser.add_argument("--review-days", type=int, default=180)
    parser.add_argument("--output", type=Path)
    args = parser.parse_args()

    with args.input.open("r", encoding="utf-8") as handle:
        document = json.load(handle)
    if not isinstance(document, dict) or not isinstance(document.get("users"), list):
        raise ValueError("Input must contain a users array")

    report = build_report(document, args.review_days)
    text = json.dumps(report, indent=2)
    if args.output:
        args.output.write_text(text + "\n", encoding="utf-8")
    else:
        print(text)
    return 0

if __name__ == "__main__":
    raise SystemExit(main())
